/** Admin portal top bar height — matches `StickyScroll.Root` `top` offset. */
export const ADMIN_PORTAL_HEADER_HEIGHT_PX = 56;

/** Minimum sticky offset used by Commercial Results when no measured value is passed. */
export const STICKY_NAVIGATION_TOP_OFFSET_FALLBACK_PX = 155;

/** Base cover height above the sticky card header (`::before` pseudo-element). */
export const STICKY_HEADER_BASE_COVER_PX = 15;

const parseOffsetPx = (offset?: string) => {
  if (!offset) {
    return STICKY_NAVIGATION_TOP_OFFSET_FALLBACK_PX;
  }

  return Number.parseInt(offset, 10);
};

/** Sticky `top` aligned with Commercial Results (minimum fallback). */
export const resolveStickyTopOffset = (measuredTopOffset?: string) => {
  const measuredPx = parseOffsetPx(measuredTopOffset);

  return `${Math.max(measuredPx, STICKY_NAVIGATION_TOP_OFFSET_FALLBACK_PX)}px`;
};

/**
 * Covers the gap between nav bottom and sticky top so content does not leak
 * while preserving the Commercial Results padding.
 */
export const stickyHeaderCoverHeight = (measuredTopOffset?: string) => {
  const measuredPx = parseOffsetPx(measuredTopOffset);
  const stickyTopPx = Math.max(
    measuredPx,
    STICKY_NAVIGATION_TOP_OFFSET_FALLBACK_PX,
  );

  return `${stickyTopPx - measuredPx + STICKY_HEADER_BASE_COVER_PX}px`;
};
